. (Join-Path $PSScriptRoot 'TestHarness.ps1')
$script:N=0;function A($id,$ok,$m){$script:N++;if(!$ok){throw "$id failed: $m"};Write-Host "$id PASS $m"}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('rap-intake-b-'+[guid]::NewGuid());New-Item $temp -ItemType Directory|Out-Null
try{$db=Join-Path $temp 'intake.db';$c=New-RapIntakeContext @() @() @((New-RapIntakeFixture)) $db;$r=Open-RapResearchIntakeStore $db;A RS01 ($r.Inbox['C-001'].State-eq'INBOXED') 'INBOXED survives restart';$p=Promote-RapFixture $c;$r=Open-RapResearchIntakeStore $db;A RS02 ($r.Promotions['C-001'].PromotionHash-eq$p.PromotionHash) 'PROMOTED survives restart';$i=Resolve-RapCanonicalPaperIdentity $c.Store $p;$r=Open-RapResearchIntakeStore $db;A RS03 ($r.IdentityResults['C-001'].CanonicalKey-eq$i.CanonicalKey) 'identity survives restart';$d=Get-RapPreZoteroDedupDecision $c.Store $p $i;$r=Open-RapResearchIntakeStore $db;A RS04 ($r.LookupResults['C-001'].CanonicalStatus-eq'NONE') 'dedup lookup lineage survives restart';A RS05 ($r.Decisions['C-001'].Decision-eq'CREATE_CANDIDATE'-and(Get-RapResearchIntakeRecoveryStatus $r C-001).Status-eq'ALREADY_COMPLETED') 'CREATE decision replay safe';$e=[pscustomobject]@{CanonicalKey='doi:10.1234/rap.001';ZoteroItemId='Z1';Title='Research Intake Safety';FirstAuthor='Kim';Year='2026'};$db2=Join-Path $temp 'reuse.db';$c2=New-RapIntakeContext @($e) @($e) @((New-RapIntakeFixture)) $db2;$p2=Promote-RapFixture $c2;$null=Invoke-RapResearchIntakeDecision $c2.Store $p2;$r2=Open-RapResearchIntakeStore $db2;A RS06 ($r2.Decisions['C-001'].Decision-eq'REUSE_EXISTING') 'REUSE decision replay safe';$r.Lifecycles['C-001']='IDENTITY_RESOLVING';$r.Decisions.Remove('C-001');Save-RapResearchIntakeStore $r|Out-Null;$x=Open-RapResearchIntakeStore $db;A RS07 ((Get-RapResearchIntakeRecoveryStatus $x C-001).Status-eq'RECOVERY_REQUIRED') 'incomplete identity requires recovery';[Rap.NativeSqlite]::Execute($db,"UPDATE ResearchIntakeStore SET RecordHash='tampered' WHERE StoreId='PRIMARY';",5000);A RS08 (-not(Test-RapResearchIntakeStoreIntegrity $db)) 'tampered candidate store blocked';A RS09 (-not(Test-RapResearchIntakeStoreIntegrity $db)) 'tampered identity store blocked';$db3=Join-Path $temp 'invalid.db';$c3=New-RapIntakeContext @() @() @((New-RapIntakeFixture)) $db3;$c3.Store.Lifecycles['C-001']='VERIFIED';Save-RapResearchIntakeStore $c3.Store|Out-Null;A RS10 ((Get-RapIntakeThrown {Open-RapResearchIntakeStore $db3})-match'INVALID_STATE') 'invalid transition blocked'}finally{Remove-Item $temp -Recurse -Force}
if($script:N-ne10){throw 'Expected RS01-RS10'};Write-Host 'SPR-015 Turn B restart matrix: RS01-RS10 10/10 PASS'
